PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE schema_migrations (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  version INTEGER NOT NULL UNIQUE,
  name TEXT NOT NULL,
  applied_at TEXT NOT NULL DEFAULT (datetime('now')),
  checksum TEXT NOT NULL,
  execution_time_ms INTEGER NOT NULL
);
CREATE TABLE products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  sku TEXT UNIQUE,
  barcode TEXT UNIQUE,
  sale_price INTEGER NOT NULL CHECK(sale_price >= 0),        -- In Paise
  purchase_price INTEGER CHECK(purchase_price >= 0),         -- In Paise
  gst_percent INTEGER NOT NULL DEFAULT 500 CHECK(gst_percent >= 0), -- Basis points (5.00% = 500)
  stock_qty INTEGER NOT NULL DEFAULT 0,
  low_stock_alert INTEGER,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, track_inventory INTEGER DEFAULT 1, is_gst_inclusive INTEGER DEFAULT 1, hsn_code TEXT DEFAULT NULL);
CREATE TABLE customers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  phone TEXT UNIQUE,
  balance_due INTEGER DEFAULT 0, -- In Paise, Positive = they owe us, Negative = advance
  is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, address TEXT, email TEXT);
CREATE TABLE bills (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  bill_number TEXT UNIQUE NOT NULL,
  customer_id INTEGER,
  subtotal INTEGER NOT NULL CHECK(subtotal >= 0),          -- In Paise
  gst_total INTEGER NOT NULL CHECK(gst_total >= 0),        -- In Paise
  discount_amount INTEGER NOT NULL DEFAULT 0 CHECK(discount_amount >= 0), -- In Paise
  grand_total INTEGER NOT NULL CHECK(grand_total >= 0),    -- In Paise
  payment_mode TEXT NOT NULL CHECK(payment_mode IN ('cash', 'upi', 'mixed')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')), cgst_amount REAL NOT NULL DEFAULT 0, sgst_amount REAL NOT NULL DEFAULT 0, igst_amount REAL NOT NULL DEFAULT 0, is_printed INTEGER NOT NULL DEFAULT 0      -- Invoice lock: 1 after first print
  CHECK(is_printed IN (0, 1)),
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL
);
CREATE TABLE bill_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  bill_id INTEGER NOT NULL,
  product_id INTEGER NOT NULL,
  product_name_snapshot TEXT NOT NULL,
  quantity INTEGER NOT NULL CHECK(quantity > 0),
  unit_price INTEGER NOT NULL CHECK(unit_price >= 0),      -- In Paise
  gst_percent INTEGER NOT NULL CHECK(gst_percent >= 0),    -- Basis points
  line_total INTEGER NOT NULL CHECK(line_total >= 0), purchase_price INTEGER,      -- In Paise
  FOREIGN KEY (bill_id) REFERENCES bills(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT
);
CREATE TABLE inventory_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  product_id INTEGER NOT NULL,
  change_qty INTEGER NOT NULL,
  reason TEXT NOT NULL CHECK(reason IN ('SALE', 'MANUAL', 'ADJUSTMENT')),
  reference_id INTEGER, -- Bill ID or other reference
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE
);
CREATE TABLE license (
  id INTEGER PRIMARY KEY CHECK (id = 1), -- Singleton row
  license_key TEXT NOT NULL,
  activated_on TEXT NOT NULL DEFAULT (datetime('now')),
  expires_on TEXT NOT NULL,
  device_id TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, trial_started_on TEXT, is_trial INTEGER NOT NULL DEFAULT 1);
CREATE TABLE app_config (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  shop_name TEXT NOT NULL DEFAULT 'SmartKhata Shop',
  owner_name TEXT,
  address TEXT,
  phone TEXT,
  gst_number TEXT,
  printer_name TEXT,
  paper_size TEXT CHECK(paper_size IN ('58mm', '80mm')) DEFAULT '58mm',
  gst_enabled INTEGER DEFAULT 1 CHECK(gst_enabled IN (0, 1)),
  round_off_enabled INTEGER DEFAULT 1 CHECK(round_off_enabled IN (0, 1)),
  updated_at TEXT DEFAULT (datetime('now'))
, gst_percentage INTEGER DEFAULT 5 CHECK(gst_percentage IN (5, 12, 18)), show_logo INTEGER DEFAULT 0, show_customer_details INTEGER DEFAULT 1, footer_message TEXT DEFAULT 'Thank you! Visit Again', print_copies INTEGER DEFAULT 1, auto_print INTEGER DEFAULT 1, billing_only INTEGER DEFAULT 0, customers_enabled INTEGER DEFAULT 1, gst_exclusive_mode INTEGER DEFAULT 0, auto_backup_enabled INTEGER DEFAULT 1, auto_backup_interval_days INTEGER DEFAULT 1, auto_backup_retain_count INTEGER DEFAULT 5, last_auto_backup TEXT, google_drive_sync_enabled INTEGER DEFAULT 0, last_cloud_sync TEXT DEFAULT NULL, cloud_sync_pending INTEGER DEFAULT 0, pending_sync_path TEXT DEFAULT NULL, auto_backup_interval_unit TEXT DEFAULT 'days', privacy_policy_accepted INTEGER DEFAULT 0, auto_update_enabled INTEGER DEFAULT 1, last_referral_banner_seen TEXT, state_code TEXT DEFAULT '29', supply_type TEXT DEFAULT 'intrastate' -- 'intrastate' or 'interstate'
  CHECK(supply_type IN ('intrastate', 'interstate')), place_of_supply TEXT DEFAULT NULL);
CREATE TABLE customer_ledger (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  customer_id INTEGER NOT NULL,
  amount INTEGER NOT NULL,                             -- In Paise (absolute amount)
  type TEXT NOT NULL CHECK(type IN ('SALE', 'PAYMENT_IN', 'PAYMENT_OUT', 'OPENING_BALANCE')),
  reference_id INTEGER,                                -- Bill ID or other reference depending on type
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE CASCADE
);
CREATE TABLE credit_notes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  credit_note_number TEXT UNIQUE NOT NULL,        -- e.g. CN-20260226-0001
  original_bill_id INTEGER,                       -- Original bill being reversed (nullable for manual CNs)
  original_bill_number TEXT,                      -- Snapshot of original bill number
  customer_id INTEGER,                            -- Customer (if applicable)
  reason TEXT NOT NULL,                           -- Return reason: 'DEFECTIVE', 'EXCESS', 'WRONG_ITEM', 'OTHER'
  refund_amount REAL NOT NULL CHECK(refund_amount >= 0),   -- Total refund amount
  taxable_amount REAL NOT NULL DEFAULT 0,         -- Taxable value being reversed
  cgst_amount REAL NOT NULL DEFAULT 0,            -- CGST reversed
  sgst_amount REAL NOT NULL DEFAULT 0,            -- SGST reversed
  igst_amount REAL NOT NULL DEFAULT 0,            -- IGST reversed
  gst_total REAL NOT NULL DEFAULT 0,              -- Total GST reversed
  notes TEXT,                                     -- Additional notes
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY (original_bill_id) REFERENCES bills(id) ON DELETE SET NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL
);
CREATE TABLE credit_note_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  credit_note_id INTEGER NOT NULL,
  product_id INTEGER NOT NULL,
  product_name_snapshot TEXT NOT NULL,
  hsn_code TEXT,
  quantity INTEGER NOT NULL CHECK(quantity > 0),
  unit_price REAL NOT NULL CHECK(unit_price >= 0),
  gst_percent REAL NOT NULL CHECK(gst_percent >= 0),
  line_taxable REAL NOT NULL DEFAULT 0,           -- Taxable amount for this line
  line_cgst REAL NOT NULL DEFAULT 0,
  line_sgst REAL NOT NULL DEFAULT 0,
  line_igst REAL NOT NULL DEFAULT 0,
  line_total REAL NOT NULL CHECK(line_total >= 0),
  FOREIGN KEY (credit_note_id) REFERENCES credit_notes(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT
);
CREATE TABLE purchases (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  purchase_number TEXT UNIQUE NOT NULL,           -- Auto-generated: PUR-YYYYMMDD-NNNN
  supplier_name TEXT NOT NULL,                    -- Supplier / vendor name
  supplier_gstin TEXT,                            -- Supplier GSTIN (optional but needed for ITC)
  invoice_number TEXT,                            -- Supplier's own invoice number
  invoice_date TEXT NOT NULL,                     -- Date of supplier invoice (YYYY-MM-DD)
  total_taxable REAL NOT NULL CHECK(total_taxable >= 0),   -- Total taxable value
  cgst_amount REAL NOT NULL DEFAULT 0,            -- Total CGST paid to supplier
  sgst_amount REAL NOT NULL DEFAULT 0,            -- Total SGST paid to supplier
  igst_amount REAL NOT NULL DEFAULT 0,            -- Total IGST paid to supplier
  gst_total REAL NOT NULL DEFAULT 0,              -- Total GST paid (ITC available)
  grand_total REAL NOT NULL CHECK(grand_total >= 0),       -- Total invoice value
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE purchase_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  purchase_id INTEGER NOT NULL,
  product_id INTEGER,                             -- Linked product (optional)
  product_name TEXT NOT NULL,                     -- Product/item name (snapshot)
  hsn_code TEXT,                                  -- HSN/SAC code
  quantity REAL NOT NULL CHECK(quantity > 0),
  unit_price REAL NOT NULL CHECK(unit_price >= 0),
  gst_percent REAL NOT NULL DEFAULT 0 CHECK(gst_percent >= 0),
  line_taxable REAL NOT NULL DEFAULT 0,
  line_cgst REAL NOT NULL DEFAULT 0,
  line_sgst REAL NOT NULL DEFAULT 0,
  line_igst REAL NOT NULL DEFAULT 0,
  line_total REAL NOT NULL CHECK(line_total >= 0),
  FOREIGN KEY (purchase_id) REFERENCES purchases(id) ON DELETE CASCADE,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE SET NULL
);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_schema_migrations_version 
ON schema_migrations(version);
CREATE INDEX idx_schema_migrations_applied_at 
ON schema_migrations(applied_at);
CREATE INDEX idx_products_name ON products(name);
CREATE INDEX idx_products_sku ON products(sku);
CREATE INDEX idx_products_barcode ON products(barcode);
CREATE INDEX idx_products_is_active ON products(is_active);
CREATE INDEX idx_customers_phone ON customers(phone);
CREATE INDEX idx_customers_name ON customers(name);
CREATE INDEX idx_customers_is_active ON customers(is_active);
CREATE INDEX idx_bills_bill_number ON bills(bill_number);
CREATE INDEX idx_bills_customer_id ON bills(customer_id);
CREATE INDEX idx_bills_created_at ON bills(created_at);
CREATE INDEX idx_bill_items_bill_id ON bill_items(bill_id);
CREATE INDEX idx_bill_items_product_id ON bill_items(product_id);
CREATE INDEX idx_inventory_logs_product_id ON inventory_logs(product_id);
CREATE INDEX idx_inventory_logs_reason ON inventory_logs(reason);
CREATE INDEX idx_inventory_logs_created_at ON inventory_logs(created_at);
CREATE INDEX idx_customer_ledger_customer_id ON customer_ledger(customer_id);
CREATE INDEX idx_customer_ledger_created_at ON customer_ledger(created_at);
CREATE INDEX idx_credit_notes_number ON credit_notes(credit_note_number);
CREATE INDEX idx_credit_notes_original_bill ON credit_notes(original_bill_id);
CREATE INDEX idx_credit_notes_created_at ON credit_notes(created_at);
CREATE INDEX idx_credit_note_items_cn_id ON credit_note_items(credit_note_id);
CREATE INDEX idx_purchases_number ON purchases(purchase_number);
CREATE INDEX idx_purchases_supplier ON purchases(supplier_name);
CREATE INDEX idx_purchases_invoice_date ON purchases(invoice_date);
CREATE INDEX idx_purchases_created_at ON purchases(created_at);
CREATE INDEX idx_purchase_items_purchase_id ON purchase_items(purchase_id);
PRAGMA writable_schema=OFF;
COMMIT;
